package org.sleepwell.app;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;

/** Actual arm/claim/request receipts. No persisted row can itself resume a timer or request output. */
final class DreamCueTables {
    static final Set<String> STATES=Set.of("ARMED","FINISHED","CANCELLED","INTERRUPTED","ERROR");
    static final Set<String> RESULTS=Set.of("CLAIMED","REQUESTED","FAILED","SKIPPED","CANCELLED","UNCERTAIN");
    static final Set<String> ISSUES=Set.of("","late","unsupported","output","storage","settings","paused","ended","alarm","process","cancelled","owner");
    static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS dream_cue_runs(nonce TEXT PRIMARY KEY,session INTEGER NOT NULL,record_start INTEGER NOT NULL,created INTEGER NOT NULL,armed_active INTEGER NOT NULL,initial_ms INTEGER NOT NULL,interval_ms INTEGER NOT NULL,cue_count INTEGER NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL,finished INTEGER,issue TEXT NOT NULL,local_owner TEXT NOT NULL DEFAULT '',UNIQUE(session,record_start))");db.execSQL("CREATE TABLE IF NOT EXISTS dream_cue_requests(nonce TEXT NOT NULL,ordinal INTEGER NOT NULL,due_active INTEGER NOT NULL,claimed INTEGER NOT NULL,requested INTEGER,mask_start INTEGER,mask_end INTEGER,result TEXT NOT NULL,issue TEXT NOT NULL,PRIMARY KEY(nonce,ordinal))");db.execSQL("CREATE TRIGGER IF NOT EXISTS dream_delete_session BEFORE DELETE ON sessions BEGIN DELETE FROM dream_cue_requests WHERE nonce IN(SELECT nonce FROM dream_cue_runs WHERE session=OLD.id);DELETE FROM dream_cue_runs WHERE session=OLD.id;END");}
    static void arm(Store store,JSONObject row,String owner)throws JSONException{SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject night=owner(store,row.getLong("session"),row.getLong("record_start"));if(!night.isNull("end"))throw new IllegalStateException("The recording has already ended.");DreamCueBackup.run(row,night);if(!store.rows("SELECT nonce FROM dream_cue_runs WHERE session=? AND record_start=?",""+row.getLong("session"),""+row.getLong("record_start")).isEmpty())throw new IllegalStateException("This night already has a cue journal. Missed or cancelled requests cannot be replayed.");ContentValues owned=PairMotionTables.values(row);owned.put("local_owner",owner);db.insertOrThrow("dream_cue_runs",null,owned);db.setTransactionSuccessful();}finally{db.endTransaction();}}
    static boolean claim(Store store,String nonce,String owner,int ordinal,long active,long at,String skipped)throws JSONException{SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject run=lookup(store,nonce,owner);if(!run.getString("state").equals("ARMED"))return false;JSONObject night=owner(store,run.getLong("session"),run.getLong("record_start"));if(!night.isNull("end"))return false;long due=run.getLong("initial_ms")+ordinal*run.getLong("interval_ms");if(ordinal<0||ordinal>=run.getInt("cue_count")||active<due||!store.rows("SELECT ordinal FROM dream_cue_requests WHERE nonce=? AND ordinal=?",nonce,""+ordinal).isEmpty())return false;JSONObject row=new JSONObject().put("nonce",nonce).put("ordinal",ordinal).put("due_active",due).put("claimed",at).put("requested",JSONObject.NULL).put("mask_start",JSONObject.NULL).put("mask_end",JSONObject.NULL).put("result",skipped.isEmpty()?"CLAIMED":"SKIPPED").put("issue",skipped);DreamCueBackup.request(row,run,night);db.insertOrThrow("dream_cue_requests",null,PairMotionTables.values(row));db.setTransactionSuccessful();return true;}finally{db.endTransaction();}}
    static void result(Store store,String nonce,String owner,int ordinal,String result,String issue,Long requested,Long maskStart,Long maskEnd)throws JSONException{SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject run=lookup(store,nonce,owner),night=owner(store,run.getLong("session"),run.getLong("record_start"));List<JSONObject> rows=store.rows("SELECT * FROM dream_cue_requests WHERE nonce=? AND ordinal=?",nonce,""+ordinal);if(rows.size()!=1||!rows.get(0).getString("result").equals("CLAIMED"))return;JSONObject row=rows.get(0);row.put("result",result).put("issue",issue).put("requested",requested==null?JSONObject.NULL:requested).put("mask_start",maskStart==null?JSONObject.NULL:maskStart).put("mask_end",maskEnd==null?JSONObject.NULL:maskEnd);DreamCueBackup.request(row,run,night);if(db.update("dream_cue_requests",PairMotionTables.values(row),"nonce=? AND ordinal=? AND result='CLAIMED'",new String[]{nonce,""+ordinal})!=1)throw new IllegalStateException("The cue claim changed.");db.setTransactionSuccessful();}finally{db.endTransaction();}}
    static void finish(Store store,String nonce,String owner,String state,String issue,long at)throws JSONException{if(!STATES.contains(state)||state.equals("ARMED")||!ISSUES.contains(issue))throw new IllegalArgumentException("Invalid cue completion");ContentValues values=new ContentValues();values.put("state",state);values.put("issue",issue);values.put("finished",at);store.getWritableDatabase().update("dream_cue_runs",values,"nonce=? AND local_owner=? AND (state='ARMED' OR state='FINISHED' AND ?='ERROR')",new String[]{nonce,owner,state});}
    static void recover(Store store,Set<String> live){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(JSONObject run:store.rows("SELECT * FROM dream_cue_runs WHERE state='ARMED'")){String nonce=run.optString("nonce");if(live.contains(nonce))continue;ContentValues state=new ContentValues();state.put("state","INTERRUPTED");state.put("issue","process");state.putNull("finished");db.update("dream_cue_runs",state,"nonce=? AND state='ARMED'",new String[]{nonce});ContentValues request=new ContentValues();request.put("result","UNCERTAIN");request.put("issue","process");db.update("dream_cue_requests",request,"nonce=? AND result='CLAIMED'",new String[]{nonce});}db.setTransactionSuccessful();}finally{db.endTransaction();}}
    private static JSONObject lookup(Store store,String nonce,String owner){List<JSONObject> rows=store.rows("SELECT * FROM dream_cue_runs WHERE nonce=? AND local_owner=?",nonce,owner);if(rows.size()!=1)throw new IllegalStateException("The cue journal no longer exists.");JSONObject row=rows.get(0);row.remove("local_owner");return row;}
    private static JSONObject owner(Store store,long session,long start){List<JSONObject> rows=store.rows("SELECT * FROM sessions WHERE id=?",""+session);if(rows.size()!=1||rows.get(0).optLong("start")!=start||!rows.get(0).optString("source").equals("tracked")||!Set.of(SensorProvenance.MOTION,SensorProvenance.SONAR).contains(rows.get(0).optString("sensor")))throw new IllegalStateException("The original tracked night changed.");return rows.get(0);}
    private DreamCueTables(){}
}
